import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> words = new ArrayList<>();
        words.add("hello");
        words.add("world");
        words.add("java");

        words.stream()
                .map(String::toUpperCase)
                .forEach(System.out::println);
    }
}
